import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Table, Form, Modal } from 'react-bootstrap';
import { apiService } from '../services/api';
import { useAuth } from '../contexts/AuthContext';
import LoadingSpinner from '../components/LoadingSpinner';
import Toast from '../components/Toast';

interface WasteItem {
  item_description: string;
  quantity: number;
  unit: string;
  or_number: string;
  or_amount: number;
  disposal_method: 'Destroyed' | 'Sold at private sale' | 'Sold at public auction' | 'Transferred' | 'Other';
  remarks?: string;
}

interface WasteMaterialsReport {
  id?: string;
  report_number: string;
  agency: string;
  place_of_storage: string;
  report_date: string;
  items: WasteItem[];
  total_amount: number;
  certified_by: string;
  certified_by_designation: string;
  approved_by: string;
  approved_by_designation: string;
  property_inspector: string;
  witness_to_disposition: string;
  status: 'Draft' | 'Submitted';
}

const WasteMaterialsReport: React.FC = () => {
  const { user } = useAuth();
  const [reports, setReports] = useState<WasteMaterialsReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
  const [selectedReport, setSelectedReport] = useState<WasteMaterialsReport | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');
  const [showToast, setShowToast] = useState(false);

  const [currentReport, setCurrentReport] = useState<WasteMaterialsReport>({
    report_number: '',
    agency: '',
    place_of_storage: '',
    report_date: new Date().toISOString().split('T')[0],
    items: [],
    total_amount: 0,
    certified_by: user?.full_name || '',
    certified_by_designation: '',
    approved_by: '',
    approved_by_designation: '',
    property_inspector: '',
    witness_to_disposition: '',
    status: 'Draft'
  });

  const [newItem, setNewItem] = useState<WasteItem>({
    item_description: '',
    quantity: 0,
    unit: '',
    or_number: '',
    or_amount: 0,
    disposal_method: 'Destroyed',
    remarks: ''
  });

  useEffect(() => {
    fetchWasteMaterialsReports();
  }, []);

  const fetchWasteMaterialsReports = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await apiService.getWasteMaterialsReports();
      setReports(data || []);
    } catch (err) {
      setError('Failed to load waste materials reports');
      console.error(err);
      setReports([]);
    } finally {
      setLoading(false);
    }
  };

  const handleAddItem = () => {
    if (!newItem.item_description || !newItem.or_number) {
      setToastMessage('Please fill in item description and O.R. number');
      setToastType('warning');
      setShowToast(true);
      return;
    }

    setCurrentReport({
      ...currentReport,
      items: [...currentReport.items, newItem],
      total_amount: currentReport.total_amount + newItem.or_amount
    });

    setNewItem({
      item_description: '',
      quantity: 0,
      unit: '',
      or_number: '',
      or_amount: 0,
      disposal_method: 'Destroyed',
      remarks: ''
    });
  };

  const handleRemoveItem = (index: number) => {
    const removedItem = currentReport.items[index];
    setCurrentReport({
      ...currentReport,
      items: currentReport.items.filter((_, i) => i !== index),
      total_amount: currentReport.total_amount - removedItem.or_amount
    });
  };

  const handleSave = async () => {
    try {
      if (!currentReport.report_number || !currentReport.agency) {
        setToastMessage('Please fill in all required fields');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      if (currentReport.items.length === 0) {
        setToastMessage('Please add at least one item');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      if (!currentReport.certified_by || !currentReport.approved_by) {
        setToastMessage('Please fill in Certified By and Approved By fields');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      const { id, ...reportDataToSend } = currentReport;
      await apiService.createWasteMaterialsReport(reportDataToSend);

      setToastMessage('Waste Materials Report saved successfully');
      setToastType('success');
      setShowToast(true);
      setShowModal(false);
      
      setCurrentReport({
        report_number: '',
        agency: '',
        place_of_storage: '',
        report_date: new Date().toISOString().split('T')[0],
        items: [],
        total_amount: 0,
        certified_by: user?.full_name || '',
        certified_by_designation: '',
        approved_by: '',
        approved_by_designation: '',
        property_inspector: '',
        witness_to_disposition: '',
        status: 'Draft'
      });

      setNewItem({
        item_description: '',
        quantity: 0,
        unit: '',
        or_number: '',
        or_amount: 0,
        disposal_method: 'Destroyed',
        remarks: ''
      });

      fetchWasteMaterialsReports();
    } catch (err) {
      setToastMessage('Failed to save waste materials report');
      setToastType('error');
      setShowToast(true);
    }
  };

  const filteredReports = reports.filter(report =>
    report.report_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
    report.agency.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <LoadingSpinner size="lg" text="Loading Waste Materials Reports..." />;

  return (
    <Container fluid className="py-4">
      {error && (
        <Row className="mb-3">
          <Col>
            <div className="alert alert-danger">{error}</div>
          </Col>
        </Row>
      )}

      <Row className="mb-4">
        <Col md={8}>
          <h2 className="fw-bold">
            <i className="bi bi-exclamation-triangle me-2"></i>
            Waste Materials Report
          </h2>
          <p className="text-muted">Manage and track waste materials disposal</p>
        </Col>
        <Col md={4} className="text-end">
          <Button
            variant="primary"
            onClick={() => {
              setCurrentReport({
                report_number: '',
                agency: '',
                place_of_storage: '',
                report_date: new Date().toISOString().split('T')[0],
                items: [],
                total_amount: 0,
                certified_by: user?.full_name || '',
                certified_by_designation: '',
                approved_by: '',
                approved_by_designation: '',
                property_inspector: '',
                witness_to_disposition: '',
                status: 'Draft'
              });
              setNewItem({
                item_description: '',
                quantity: 0,
                unit: '',
                or_number: '',
                or_amount: 0,
                disposal_method: 'Destroyed',
                remarks: ''
              });
              setShowModal(true);
            }}
          >
            <i className="bi bi-plus-circle me-2"></i>
            New Report
          </Button>
        </Col>
      </Row>

      <Row className="mb-3">
        <Col md={6}>
          <Form.Group>
            <Form.Control
              placeholder="Search by report number or agency..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              size="sm"
            />
          </Form.Group>
        </Col>
      </Row>

      <Row>
        <Col>
          <Card className="shadow-sm">
            <Card.Body className="p-0">
              <Table hover className="mb-0">
                <thead className="table-light">
                  <tr>
                    <th>Report No.</th>
                    <th>Agency</th>
                    <th>Report Date</th>
                    <th>Total Amount</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredReports.length === 0 ? (
                    <tr>
                      <td colSpan={6} className="text-center py-4 text-muted">
                        No waste materials reports found
                      </td>
                    </tr>
                  ) : (
                    filteredReports.map((report) => (
                      <tr key={report.id}>
                        <td className="fw-bold">{report.report_number}</td>
                        <td>{report.agency}</td>
                        <td>{report.report_date}</td>
                        <td className="text-end">₱{report.total_amount.toFixed(2)}</td>
                        <td>
                          <span className={`badge bg-${report.status === 'Submitted' ? 'success' : 'warning'}`}>
                            {report.status}
                          </span>
                        </td>
                        <td>
                          <Button
                            variant="info"
                            size="sm"
                            onClick={() => {
                              setSelectedReport(report);
                              setShowViewModal(true);
                            }}
                          >
                            <i className="bi bi-eye"></i>
                          </Button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            <i className="bi bi-file-earmark-plus me-2"></i>
            New Waste Materials Report
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className="bg-light">
          <Form>
            <div className="text-center mb-4">
              <h5 className="fw-bold">WASTE MATERIALS REPORT</h5>
              <p className="small mb-1">CAVITE STATE UNIVERSITY</p>
            </div>

            <Row className="mb-3">
              <Col md={4}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Report Number *</Form.Label>
                  <Form.Control
                    value={currentReport.report_number}
                    onChange={(e) => setCurrentReport({ ...currentReport, report_number: e.target.value })}
                    placeholder="No."
                    size="sm"
                  />
                </Form.Group>
              </Col>
              <Col md={4}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Agency *</Form.Label>
                  <Form.Control
                    value={currentReport.agency}
                    onChange={(e) => setCurrentReport({ ...currentReport, agency: e.target.value })}
                    placeholder="Agency"
                    size="sm"
                  />
                </Form.Group>
              </Col>
              <Col md={4}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Date *</Form.Label>
                  <Form.Control
                    type="date"
                    value={currentReport.report_date}
                    onChange={(e) => setCurrentReport({ ...currentReport, report_date: e.target.value })}
                    size="sm"
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row className="mb-3">
              <Col md={12}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Place of Storage</Form.Label>
                  <Form.Control
                    value={currentReport.place_of_storage}
                    onChange={(e) => setCurrentReport({ ...currentReport, place_of_storage: e.target.value })}
                    placeholder="Place of Storage"
                    size="sm"
                  />
                </Form.Group>
              </Col>
            </Row>

            <Card className="mb-3">
              <Card.Header className="bg-light d-flex justify-content-between align-items-center">
                <h6 className="mb-0 fw-bold">ITEMS FOR DISPOSAL</h6>
                <span className="fw-bold text-primary">Total: ₱{currentReport.total_amount.toFixed(2)}</span>
              </Card.Header>
              <Card.Body>
                <Row className="mb-3 pb-3 border-bottom">
                  <Col md={2}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small fw-bold">Qty.</Form.Label>
                      <Form.Control
                        type="number"
                        value={newItem.quantity}
                        onChange={(e) => setNewItem({ ...newItem, quantity: parseInt(e.target.value) || 0 })}
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={2}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small fw-bold">Unit</Form.Label>
                      <Form.Control
                        value={newItem.unit}
                        onChange={(e) => setNewItem({ ...newItem, unit: e.target.value })}
                        placeholder="Unit"
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small fw-bold">Description *</Form.Label>
                      <Form.Control
                        value={newItem.item_description}
                        onChange={(e) => setNewItem({ ...newItem, item_description: e.target.value })}
                        placeholder="Item Description"
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={2}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small fw-bold">O.R. No. *</Form.Label>
                      <Form.Control
                        value={newItem.or_number}
                        onChange={(e) => setNewItem({ ...newItem, or_number: e.target.value })}
                        placeholder="O.R. #"
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={2}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small fw-bold">Amount</Form.Label>
                      <Form.Control
                        type="number"
                        step="0.01"
                        value={newItem.or_amount}
                        onChange={(e) => setNewItem({ ...newItem, or_amount: parseFloat(e.target.value) || 0 })}
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={1} className="d-flex align-items-end">
                    <Button variant="success" size="sm" onClick={handleAddItem} className="w-100">
                      <i className="bi bi-plus"></i>
                    </Button>
                  </Col>
                </Row>

                <Row className="mb-3">
                  <Col md={12}>
                    <Form.Group>
                      <Form.Label className="small fw-bold">Disposal Method</Form.Label>
                      <div className="d-flex flex-wrap gap-3">
                        {['Destroyed', 'Sold at private sale', 'Sold at public auction', 'Transferred', 'Other'].map((method) => (
                          <Form.Check
                            key={method}
                            type="radio"
                            label={method}
                            value={method}
                            checked={newItem.disposal_method === method}
                            onChange={(e) => setNewItem({ ...newItem, disposal_method: e.target.value as any })}
                          />
                        ))}
                      </div>
                    </Form.Group>
                  </Col>
                </Row>

                {currentReport.items.length > 0 && (
                  <Table size="sm" className="mt-3">
                    <thead className="table-light">
                      <tr>
                        <th className="text-center">Qty.</th>
                        <th>Unit</th>
                        <th>Description</th>
                        <th>O.R. No.</th>
                        <th className="text-end">Amount</th>
                        <th>Method</th>
                        <th>Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {currentReport.items.map((item, index) => (
                        <tr key={index}>
                          <td className="text-center">{item.quantity}</td>
                          <td>{item.unit}</td>
                          <td>{item.item_description}</td>
                          <td>{item.or_number}</td>
                          <td className="text-end">₱{item.or_amount.toFixed(2)}</td>
                          <td><small>{item.disposal_method}</small></td>
                          <td>
                            <Button
                              variant="danger"
                              size="sm"
                              onClick={() => handleRemoveItem(index)}
                            >
                              <i className="bi bi-trash"></i>
                            </Button>
                          </td>
                        </tr>
                      ))}
                      <tr className="fw-bold table-light">
                        <td colSpan={4} className="text-end">TOTAL:</td>
                        <td className="text-end">₱{currentReport.total_amount.toFixed(2)}</td>
                        <td></td>
                        <td></td>
                      </tr>
                    </tbody>
                  </Table>
                )}
              </Card.Body>
            </Card>

            <Card className="mb-3">
              <Card.Header className="bg-light">
                <h6 className="mb-0 fw-bold">CERTIFICATION</h6>
              </Card.Header>
              <Card.Body>
                <Row className="mb-3">
                  <Col md={6}>
                    <p className="small mb-2 fw-bold">Certified Correct</p>
                    <Form.Group>
                      <Form.Label className="small">OIC - Supply and Property Office *</Form.Label>
                      <Form.Control
                        value={currentReport.certified_by}
                        onChange={(e) => setCurrentReport({ ...currentReport, certified_by: e.target.value })}
                        placeholder="Name"
                        size="sm"
                      />
                    </Form.Group>
                    <Form.Group className="mt-2">
                      <Form.Label className="small">Designation</Form.Label>
                      <Form.Control
                        value={currentReport.certified_by_designation}
                        onChange={(e) => setCurrentReport({ ...currentReport, certified_by_designation: e.target.value })}
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={6}>
                    <p className="small mb-2 fw-bold">Disposal Approved</p>
                    <Form.Group>
                      <Form.Label className="small">President *</Form.Label>
                      <Form.Control
                        value={currentReport.approved_by}
                        onChange={(e) => setCurrentReport({ ...currentReport, approved_by: e.target.value })}
                        placeholder="Name"
                        size="sm"
                      />
                    </Form.Group>
                    <Form.Group className="mt-2">
                      <Form.Label className="small">Designation</Form.Label>
                      <Form.Control
                        value={currentReport.approved_by_designation}
                        onChange={(e) => setCurrentReport({ ...currentReport, approved_by_designation: e.target.value })}
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                </Row>
              </Card.Body>
            </Card>

            <Card className="mb-3">
              <Card.Header className="bg-light">
                <h6 className="mb-0 fw-bold">CERTIFICATE OF INSPECTION</h6>
              </Card.Header>
              <Card.Body>
                <p className="small mb-3">I hereby certify that the property enumerated above was disposed of as follows:</p>
                
                <Row className="mb-3">
                  <Col md={6}>
                    <Form.Group>
                      <Form.Label className="small">Property Inspector (Name & Signature)</Form.Label>
                      <Form.Control
                        value={currentReport.property_inspector}
                        onChange={(e) => setCurrentReport({ ...currentReport, property_inspector: e.target.value })}
                        placeholder="Property Inspector"
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={6}>
                    <Form.Group>
                      <Form.Label className="small">Witness to Disposition</Form.Label>
                      <Form.Control
                        value={currentReport.witness_to_disposition}
                        onChange={(e) => setCurrentReport({ ...currentReport, witness_to_disposition: e.target.value })}
                        placeholder="Witness"
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                </Row>
              </Card.Body>
            </Card>
          </Form>
        </Modal.Body>
        <Modal.Footer className="border-top">
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel
          </Button>
          <Button variant="primary" onClick={handleSave}>
            <i className="bi bi-check-circle me-2"></i>
            Save Report
          </Button>
        </Modal.Footer>
      </Modal>

      {selectedReport && (
        <Modal show={showViewModal} onHide={() => setShowViewModal(false)} size="lg">
          <Modal.Header closeButton>
            <Modal.Title>
              <i className="bi bi-file-earmark me-2"></i>
              Waste Materials Report - {selectedReport.report_number}
            </Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Row className="mb-3">
              <Col md={6}>
                <p className="small"><strong>Report Number:</strong> {selectedReport.report_number}</p>
                <p className="small"><strong>Agency:</strong> {selectedReport.agency}</p>
                <p className="small"><strong>Report Date:</strong> {selectedReport.report_date}</p>
              </Col>
              <Col md={6}>
                <p className="small"><strong>Place of Storage:</strong> {selectedReport.place_of_storage}</p>
                <p className="small"><strong>Total Amount:</strong> ₱{selectedReport.total_amount.toFixed(2)}</p>
                <p className="small"><strong>Status:</strong> {selectedReport.status}</p>
              </Col>
            </Row>

            <h6 className="fw-bold mt-4 mb-3">Waste Items</h6>
            <div style={{ overflowX: 'auto' }}>
              <Table size="sm" className="mb-3">
                <thead className="table-light">
                  <tr>
                    <th className="text-center">Qty.</th>
                    <th>Unit</th>
                    <th>Description</th>
                    <th>O.R. No.</th>
                    <th className="text-end">Amount</th>
                    <th>Method</th>
                  </tr>
                </thead>
                <tbody>
                  {selectedReport.items.map((item, index) => (
                    <tr key={index}>
                      <td className="text-center">{item.quantity}</td>
                      <td>{item.unit}</td>
                      <td>{item.item_description}</td>
                      <td>{item.or_number}</td>
                      <td className="text-end">₱{item.or_amount.toFixed(2)}</td>
                      <td><small>{item.disposal_method}</small></td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </div>

            <Row className="mt-4 pt-3 border-top">
              <Col md={6}>
                <p className="small"><strong>Certified By:</strong> {selectedReport.certified_by}</p>
                <p className="small"><strong>Designation:</strong> {selectedReport.certified_by_designation}</p>
              </Col>
              <Col md={6}>
                <p className="small"><strong>Approved By:</strong> {selectedReport.approved_by}</p>
                <p className="small"><strong>Designation:</strong> {selectedReport.approved_by_designation}</p>
              </Col>
            </Row>

            <Row className="mt-3">
              <Col md={6}>
                <p className="small"><strong>Property Inspector:</strong> {selectedReport.property_inspector}</p>
              </Col>
              <Col md={6}>
                <p className="small"><strong>Witness to Disposition:</strong> {selectedReport.witness_to_disposition}</p>
              </Col>
            </Row>
          </Modal.Body>
        </Modal>
      )}

      <Toast
        show={showToast}
        onClose={() => setShowToast(false)}
        message={toastMessage}
        type={toastType}
        delay={3000}
      />
    </Container>
  );
};

export default WasteMaterialsReport;
